// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface EstimateStatisticsOut {
  date_from: string;
  date_to: string;
  estimate_due_hours: number;
  admissions: number;
  explained: number;
  explained_in_time: number;
  /** MSDS PRE 78 */
  explained_in_time_pct: number | null;
  /** Moves to a ward with another daily charge */
  ward_changes: number;
  ward_changes_explained: number;
  /** MSDS PRE 79 */
  ward_changes_explained_pct: number | null;
  accuracy_pct: number;
  discharges_estimated: number;
  bills_within_accuracy: number;
  bills_within_accuracy_pct: number | null;
  by_reason: EstimateCountOut[];
}

export interface EstimateCountOut {
  key: string;
  count: number;
}

export interface EstimateWorkItemOut {
  kind: "Admission" | "ChangeOfWard";
  admission_id: number;
  admission_number: string;
  patient_id: number;
  mrn: string;
  patient_name: string;
  ward_name: string | null;
  transfer_id: number | null;
  since: string;
  /** Past estimate_due_hours */
  overdue: boolean;
  detail: string | null;
}

/** Estimate statistics — GET /api/v1/cost-estimates/statistics (who may call: holders of estimate.view). */
export function statisticsCostEstimates(query?: { date_from?: string | null; date_to?: string | null }): Promise<EstimateStatisticsOut> {
  return api<EstimateStatisticsOut>("GET", withQuery(`/cost-estimates/statistics`, query), undefined);
}

/** The uniform pricing policy (PDF) — GET /api/v1/tariff/pricing-policy/pdf (who may call: holders of estimate.view or estimate.prepare). */
export function pricingPolicyPdf(): Promise<unknown> {
  return api<unknown>("GET", `/tariff/pricing-policy/pdf`, undefined);
}

/** The tariff to print and display (PDF) — GET /api/v1/tariff/pdf (who may call: any logged-in user). */
export function tariffPdf(): Promise<unknown> {
  return api<unknown>("GET", `/tariff/pdf`, undefined);
}

/** Estimates to explain: new admissions and changes of ward — GET /api/v1/cost-estimates/worklist (who may call: holders of estimate.view or estimate.prepare or estimate.explain). */
export function worklistCostEstimates(): Promise<EstimateWorkItemOut[]> {
  return api<EstimateWorkItemOut[]>("GET", `/cost-estimates/worklist`, undefined);
}
